    "mainTitle": {
      "type": "Text",
      "props": {
        "text": "Kyoto in Autumn: Your 5-Day Family Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "introText": {
      "type": "Text",
      "props": {
        "text": "This itinerary provides a relaxed, family-friendly 5-day plan for exploring Kyoto, blending cultural landmarks with engaging activities for children aged 8 and 12. The schedule is designed for early November, a beautiful time for autumn colors."
      },
      "children": []
    },
    "tipsCard": {
      "type": "Card",
      "props": {},
      "children": [
        "tipsStack"
      ]
    },
    "tipsStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "tipsTitle",
        "tipsText1",
        "tipsText2"
      ]
    },
    "tipsTitle": {
      "type": "Text",
      "props": {
        "text": "Trip Context and Practical Tips",
        "variant": "h3"
      },
      "children": []
    },
    "tipsText1": {
      "type": "Text",
      "props": {
        "text": "This plan assumes your accommodation is centrally located for easy access to public transportation. The budget is mid-range, and all entry fees are estimates. For transport, an ICOCA or Suica card is recommended for convenience."
      },
      "children": []
    },
    "tipsText2": {
      "type": "Text",
      "props": {
        "text": "Note that early November is a peak season for autumn foliage, so expect popular sites to be busy, especially on weekends."
      },
      "children": []
    },
    "glanceCard": {
      "type": "Card",
      "props": {},
