        "day1Dinner"
      ]
    },
    "day1Title": {
      "type": "Text",
      "props": {
        "text": "Day 1: Torii Gates and Autumn Views (Tuesday, Nov 5)",
        "variant": "h3"
      },
      "children": []
    },
    "day1Morning": {
      "type": "Text",
      "props": {
        "text": "Morning: Fushimi Inari Shrine. Explore the magical red torii gates. The first 30-45 minutes are most impressive for families. Entry: Free."
      },
      "children": []
    },
    "day1Afternoon": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Tofuku-ji Temple. Famous for autumn foliage, especially the view from Tsutenkyo Bridge. Entry: Approx. ¥1000."
      },
      "children": []
    },
    "day1Dinner": {
      "type": "Text",
      "props": {
        "text": "Dinner: Kyoto Ramen Koji (Ramen Street) on the 10th floor of Kyoto Station. A casual and delicious option for the whole family."
      },
      "children": []
    },
    "day2Card": {
      "type": "Card",
      "props": {},
      "children": [
        "day2Stack"
      ]
    },
    "day2Stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "day2Title",
        "day2Morning",
        "day2Afternoon",
        "day2Dinner"
      ]
    },
    "day2Title": {
      "type": "Text",
      "props": {
        "text": "Day 2: Monkeys and Bamboo Groves (Wednesday, Nov 6)",
        "variant": "h3"
      },
      "children": []
    },
    "day2Morning": {
      "type": "Text",
      "props": {
        "text": "Morning: Arashiyama Bamboo Grove & Tenryu-ji Temple. Arrive early to avoid crowds. Visit the adjacent temple's stunning garden. Entry: Grove is free, Temple is approx. ¥500."
      },
      "children": []
    },
    "day2Afternoon": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Iwatayama Monkey Park. A 20-minute hike leads to freely roaming Japanese macaques and a panoramic city view. Entry: Approx. ¥600 Adult / ¥300 Child."
      },
      "children": []
    },
    "day2Dinner": {
      "type": "Text",
      "props": {
        "text": "Dinner: Find family-friendly restaurants near Togetsukyo Bridge serving tempura, soba, and other popular dishes."
      },
      "children": []
    },
    "day3Card": {
      "type": "Card",
      "props": {},
      "children": [
        "day3Stack"
      ]
    },
    "day3Stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "day3Title",
        "day3Morning",
        "day3Afternoon",
        "day3Dinner"
      ]
    },
    "day3Title": {
      "type": "Text",
      "props": {
        "text": "Day 3: Golden Pavilions and Samurai Action (Thursday, Nov 7)",
        "variant": "h3"
      },
      "children": []
    },
    "day3Morning": {
      "type": "Text",
      "props": {
        "text": "Morning: Kinkaku-ji (The Golden Pavilion). A picture-perfect temple covered in gold leaf, reflected in a pond. Entry: Approx. ¥500."
      },
      "children": []
    },
    "day3Afternoon": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Toei Kyoto Studio Park (Eigamura). A film set and theme park with a replica Edo-period town and live ninja shows. Entry: Approx. ¥2400 Adult / ¥1200 Child."
      },
      "children": []
    },
    "day3Dinner": {
      "type": "Text",
      "props": {
        "text": "Dinner: Find a local restaurant specializing in okonomiyaki (savory pancake) and yakisoba (fried noodles)."
      },
      "children": []
    },
    "day4Card": {
      "type": "Card",
      "props": {},
      "children": [
        "day4Stack"
      ]
    },
    "day4Stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "day4Title",
        "day4Morning",
        "day4Afternoon",
        "day4Dinner"
      ]
    },
    "day4Title": {
      "type": "Text",
      "props": {
        "text": "Day 4: Historic Streets and Market Flavors (Friday, Nov 8)",
        "variant": "h3"
      },
      "children": []
    },
    "day4Morning": {
      "type": "Text",
      "props": {
        "text": "Morning: Kiyomizu-dera Temple. A magnificent wooden temple with sweeping city views. Walk up through the historic Sannenzaka and Ninenzaka streets. Entry: Approx. ¥400."
      },
      "children": []
    },
    "day4Afternoon": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Nishiki Market. Known as 'Kyoto's Kitchen,' this bustling market is a sensory delight for trying local snacks. Entry: Free."
      },
      "children": []
    },
    "day4Dinner": {
      "type": "Text",
      "props": {
        "text": "Dinner: Stroll through the Gion district and find a restaurant serving katsu or a family-friendly izakaya."
      },
      "children": []
    },
    "day5Card": {
      "type": "Card",
      "props": {},
      "children": [
        "day5Stack"
      ]
    },
    "day5Stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "day5Title",
        "day5Morning",
        "day5Afternoon",
        "day5Dinner"
      ]
    },
    "day5Title": {
      "type": "Text",
      "props": {
        "text": "Day 5: Trains and Treasures (Saturday, Nov 9)",
        "variant": "h3"
      },
      "children": []
    },
    "day5Morning": {
      "type": "Text",
      "props": {
        "text": "Morning: Kyoto Railway Museum. A hit for all ages, featuring trains from steam locomotives to Shinkansen, with interactive exhibits. Entry: Approx. ¥1500 Adult / ¥500 Child."
      },
      "children": []
    },
    "day5Afternoon": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Last-Minute Souvenir Shopping. Explore shops in and around Kyoto Station or along Shijo-dori street."
      },
      "children": []
    },
    "day5Dinner": {
      "type": "Text",
      "props": {
        "text": "Dinner: For your final dinner, walk down the charming, lantern-lit Pontocho Alley to find a mid-range restaurant."
      },
      "children": []
    }
  }
